IR_ENTERPRISE_CSS = """
/* ==========================================================================
   IntentRadar v3.3 Enterprise B2B Intelligence Design System
   Inspired by Linear, PostHog, Tremor, Plausible & shadcn/ui
   ========================================================================== */
:root {
    --ir-bg-canvas: #f8fafc;
    --ir-bg-surface: #ffffff;
    --ir-bg-subtle: #f4f4f5;
    --ir-border: #e4e4e7;
    --ir-border-strong: #d4d4d8;
    --ir-text-main: #09090b;
    --ir-text-secondary: #52525b;
    --ir-text-muted: #71717a;
}

body {
    background-color: var(--ir-bg-canvas);
    color: var(--ir-text-main);
    font-feature-settings: "cv02", "cv03", "cv04", "cv11";
}

/* Executive Overview Dashboard Layout */
.ir-dashboard-section {
    margin-bottom: 16px;
    display: flex;
    flex-direction: column;
    gap: 12px;
}
.ir-dashboard-section.hidden {
    display: none !important;
}

.ir-overview-banner {
    background: linear-gradient(135deg, #09090b 0%, #18181b 60%, #111827 100%);
    color: #ffffff;
    border-radius: 12px;
    padding: 12px 16px;
    border: 1px solid #27272a;
    box-shadow: 0 4px 12px rgba(9, 9, 11, 0.08);
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
}

.ir-overview-banner-left {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
}

.ir-overview-pulse {
    width: 8px;
    height: 8px;
    border-radius: 9999px;
    background: #10b981;
    box-shadow: 0 0 0 4px rgba(16, 185, 129, 0.22);
    display: inline-block;
    flex-shrink: 0;
}

.ir-kpi-grid {
    display: grid;
    grid-template-columns: repeat(1, minmax(0, 1fr));
    gap: 12px;
}
@media (min-width: 640px) {
    .ir-kpi-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}
@media (min-width: 1100px) {
    .ir-kpi-grid {
        grid-template-columns: repeat(4, minmax(0, 1fr));
    }
}

.ir-kpi-card {
    background: #ffffff;
    border: 1px solid var(--ir-border);
    border-radius: 12px;
    padding: 14px 16px;
    box-shadow: 0 1px 2px rgba(9, 9, 11, 0.03);
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    gap: 8px;
    position: relative;
    overflow: hidden;
    transition: border-color 0.15s ease, box-shadow 0.15s ease;
}
.ir-kpi-card:hover {
    border-color: #d4d4d8;
    box-shadow: 0 4px 12px rgba(9, 9, 11, 0.05);
}
.ir-kpi-card::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: var(--kpi-accent, #10b981);
}
.ir-kpi-card.accent-emerald { --kpi-accent: linear-gradient(90deg, #059669, #34d399); }
.ir-kpi-card.accent-blue { --kpi-accent: linear-gradient(90deg, #2563eb, #60a5fa); }
.ir-kpi-card.accent-indigo { --kpi-accent: linear-gradient(90deg, #4f46e5, #818cf8); }
.ir-kpi-card.accent-amber { --kpi-accent: linear-gradient(90deg, #d97706, #fbbf24); }

.ir-kpi-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
}
.ir-kpi-title {
    font-size: 11px;
    font-weight: 600;
    color: var(--ir-text-secondary);
    letter-spacing: 0.01em;
}
.ir-kpi-badge {
    font-size: 10px;
    font-weight: 600;
    padding: 2px 7px;
    border-radius: 9999px;
    white-space: nowrap;
}
.ir-kpi-value-row {
    display: flex;
    align-items: baseline;
    gap: 8px;
}
.ir-kpi-number {
    font-family: "JetBrains Mono", ui-monospace, SFMono-Regular, monospace;
    font-size: 24px;
    font-weight: 700;
    line-height: 1.1;
    color: var(--ir-text-main);
    letter-spacing: -0.02em;
}
.ir-kpi-unit {
    font-size: 11px;
    font-weight: 500;
    color: var(--ir-text-muted);
}

/* Segmented Mini Progress Bar inside KPI Cards */
.ir-segmented-bar {
    height: 6px;
    width: 100%;
    background: #f4f4f5;
    border-radius: 9999px;
    overflow: hidden;
    display: flex;
    gap: 2px;
}
.ir-segmented-fill {
    height: 100%;
    transition: width 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
.ir-kpi-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    font-size: 11px;
    color: var(--ir-text-muted);
    gap: 6px;
}

/* Row 2: 3 Analytics Chart Cards */
.ir-chart-grid {
    display: grid;
    grid-template-columns: repeat(1, minmax(0, 1fr));
    gap: 12px;
}
@media (min-width: 1024px) {
    .ir-chart-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}

.ir-chart-card {
    background: #ffffff;
    border: 1px solid var(--ir-border);
    border-radius: 12px;
    padding: 14px 16px;
    box-shadow: 0 1px 2px rgba(9, 9, 11, 0.03);
    display: flex;
    flex-direction: column;
    gap: 10px;
}
.ir-chart-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding-bottom: 8px;
    border-bottom: 1px solid #f4f4f5;
}
.ir-chart-title {
    font-size: 12px;
    font-weight: 700;
    color: var(--ir-text-main);
    display: flex;
    align-items: center;
    gap: 6px;
}
.ir-chart-subtitle {
    font-size: 10px;
    color: var(--ir-text-muted);
    font-family: "JetBrains Mono", monospace;
}

/* Plausible / PostHog Interactive Bar Rows */
.ir-bar-list {
    display: flex;
    flex-direction: column;
    gap: 5px;
}
.ir-bar-item {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 5px 8px;
    border-radius: 7px;
    font-size: 11px;
    cursor: pointer;
    overflow: hidden;
    background: #fafafa;
    border: 1px solid #f4f4f5;
    transition: border-color 0.15s ease, background-color 0.15s ease;
    width: 100%;
    text-align: left;
}
.ir-bar-item:hover {
    border-color: #d4d4d8;
    background: #f4f4f5;
}
.ir-bar-item.active-bar {
    border-color: #10b981;
    background: #ecfdf5;
}
.ir-bar-bg {
    position: absolute;
    top: 0;
    bottom: 0;
    left: 0;
    border-radius: 6px;
    pointer-events: none;
    transition: width 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}
.ir-bar-content {
    position: relative;
    z-index: 1;
    display: flex;
    align-items: center;
    gap: 6px;
    font-weight: 600;
    color: #18181b;
    min-width: 0;
}
.ir-bar-metric {
    position: relative;
    z-index: 1;
    display: flex;
    align-items: center;
    gap: 6px;
    font-family: "JetBrains Mono", monospace;
    font-size: 11px;
    color: #3f3f46;
    flex-shrink: 0;
}

/* 4-Stage Funnel Rows */
.ir-funnel-list {
    display: flex;
    flex-direction: column;
    gap: 7px;
}
.ir-funnel-row {
    display: flex;
    flex-direction: column;
    gap: 4px;
    padding: 6px 9px;
    border-radius: 8px;
    background: #fafafa;
    border: 1px solid #f4f4f5;
    cursor: pointer;
    transition: all 0.15s ease;
}
.ir-funnel-row:hover {
    border-color: #d4d4d8;
    background: #f4f4f5;
}
.ir-funnel-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
    font-size: 11px;
}
.ir-funnel-track {
    height: 7px;
    width: 100%;
    background: #e4e4e7;
    border-radius: 9999px;
    overflow: hidden;
}
.ir-funnel-fill {
    height: 100%;
    border-radius: 9999px;
    transition: width 0.35s ease;
}

/* Seller Gate Customizer Card */
.ir-customizer-panel {
    background: linear-gradient(180deg, #fffbeb 0%, #ffffff 100%);
    border-bottom: 1px solid #fde68a;
    padding: 12px 18px;
}
.ir-preset-chip {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 4px 9px;
    border-radius: 6px;
    font-size: 11px;
    font-weight: 500;
    background: #ffffff;
    color: #27272a;
    border: 1px solid #e4e4e7;
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.02);
    transition: all 0.15s ease;
}
.ir-preset-chip:hover {
    background: #ecfdf5;
    color: #065f46;
    border-color: #6ee7b7;
}
.ir-form-grid {
    display: grid;
    grid-template-columns: repeat(1, minmax(0, 1fr));
    gap: 8px;
    margin-top: 8px;
}
@media (min-width: 768px) {
    .ir-form-grid {
        grid-template-columns: repeat(6, minmax(0, 1fr));
    }
}
.ir-field-group {
    display: flex;
    flex-direction: column;
    gap: 3px;
}
.ir-field-label {
    font-size: 10px;
    font-weight: 600;
    color: #52525b;
}

/* Workbench Table Enhancements */
.ir-workbench-card {
    background: #ffffff;
    border: 1px solid var(--ir-border);
    border-radius: 12px;
    box-shadow: 0 1px 3px rgba(9, 9, 11, 0.04);
    overflow: hidden;
}
.ir-workbench-toolbar {
    padding: 10px 14px;
    background: #fafafa;
    border-bottom: 1px solid var(--ir-border);
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
}
.ir-table-cell-main {
    min-width: 260px;
    max-width: 390px;
    width: 100%;
}
#tableViewWrapper table {
    width: 100%;
    border-collapse: collapse;
}
#tableViewWrapper table th,
#tableViewWrapper table td {
    padding: 9px 7px;
    vertical-align: middle;
}
#tableViewWrapper table th:first-child,
#tableViewWrapper table td:first-child {
    padding-left: 10px;
    padding-right: 4px;
    width: 32px;
}
#tableViewWrapper table th:last-child,
#tableViewWrapper table td:last-child {
    padding-right: 10px;
}
.ir-cand-sub {
    display: block;
    max-width: 132px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-size: 10px;
    color: #71717a;
}
.ir-blocker-sub {
    display: inline-block;
    max-width: 155px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-size: 10px;
    color: #a1a1aa;
    vertical-align: bottom;
}
.ir-meta-sub {
    display: block;
    max-width: 135px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-size: 10px;
    color: #b45309;
    font-weight: 500;
    margin-top: 2px;
}
.ir-disq-sub {
    display: block;
    max-width: 82px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-size: 10px;
    color: #e11d48;
}
.ir-post-title {
    font-size: 12.5px;
    font-weight: 600;
    color: #09090b;
    line-height: 1.38;
    margin-bottom: 4px;
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
    overflow: hidden;
}
.group:hover .ir-post-title {
    color: #059669;
}
.ir-quote-callout {
    font-size: 11px;
    color: #3f3f46;
    background: #f8fafc;
    border-left: 3px solid #10b981;
    border-top: 1px solid #e2e8f0;
    border-right: 1px solid #e2e8f0;
    border-bottom: 1px solid #e2e8f0;
    padding: 5px 8px;
    border-radius: 0 6px 6px 0;
    margin-bottom: 5px;
    font-style: italic;
}
.ir-quote-text {
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
    overflow: hidden;
    line-height: 1.42;
}

/* Upgraded Human Verification Panel (.review-panel) */
.review-panel {
    padding: 14px;
    background: linear-gradient(180deg, #f8fafc 0%, #ffffff 100%);
    border: 1px solid #cbd5e1;
    border-radius: 10px;
    font-size: 12px;
    margin: 10px 0;
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.03);
}
.review-panel strong {
    font-size: 12px;
    font-weight: 700;
    color: #0f172a;
    display: flex;
    align-items: center;
    gap: 6px;
}
.review-panel p {
    font-size: 11px;
    color: #64748b;
    margin: 4px 0 10px 0;
    line-height: 1.45;
}
.review-panel label {
    display: block;
    margin: 8px 0;
    font-size: 11px;
    font-weight: 600;
    color: #334155;
}
.review-panel input:not([type="checkbox"]),
.review-panel textarea,
.review-panel select {
    display: block;
    width: 100%;
    margin-top: 4px;
    padding: 6px 9px;
    font-size: 12px;
    font-weight: 400;
    color: #0f172a;
    background: #ffffff;
    border: 1px solid #cbd5e1;
    border-radius: 6px;
    transition: border-color 0.15s ease, box-shadow 0.15s ease;
}
.review-panel input:not([type="checkbox"]):focus,
.review-panel textarea:focus,
.review-panel select:focus {
    outline: none;
    border-color: #0f172a;
    box-shadow: 0 0 0 2px rgba(15, 23, 42, 0.1);
}
.review-panel textarea {
    min-height: 54px;
}
.review-panel button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 6px 12px;
    margin: 6px 6px 2px 0;
    font-size: 11px;
    font-weight: 600;
    background: #09090b;
    color: #ffffff;
    border-radius: 6px;
    border: 1px solid #09090b;
    transition: background-color 0.15s ease;
}
.review-panel button:hover {
    background: #27272a;
}
.review-panel button[data-action="export-review-profile"] {
    background: #ffffff;
    color: #18181b;
    border: 1px solid #d4d4d8;
}
.review-panel button[data-action="export-review-profile"]:hover {
    background: #f4f4f5;
}
"""

COMPILED_TAILWIND_CSS = COMPILED_TAILWIND_CSS + "\n" + IR_ENTERPRISE_CSS
